insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-mozart-trivia',
  'Mozart Trivia: Life, Operas and the Requiem',
  'Eight questions on Wolfgang Amadeus Mozart: his Salzburg childhood, the great operas, Eine kleine Nachtmusik and the Requiem he left unfinished.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'music'),
  '[{"id":"q1","question":"In which city was Mozart born in 1756?","options":[{"id":"a","text":"Vienna","is_correct":false},{"id":"b","text":"Salzburg","is_correct":true},{"id":"c","text":"Prague","is_correct":false},{"id":"d","text":"Munich","is_correct":false}],"explanation":"Wolfgang Amadeus Mozart was born in Salzburg on 27 January 1756; he moved to Vienna as an adult in 1781."},{"id":"q2","question":"As a child prodigy, Mozart toured Europe performing alongside which family member?","options":[{"id":"a","text":"His mother Anna Maria","is_correct":false},{"id":"b","text":"His sister Maria Anna, \"Nannerl\"","is_correct":true},{"id":"c","text":"His younger brother","is_correct":false},{"id":"d","text":"His cousin the \"Bäsle\"","is_correct":false}],"explanation":"Maria Anna Mozart, nicknamed Nannerl, was also a keyboard prodigy; the siblings toured Europe together as children."},{"id":"q3","question":"Which Mozart opera features the Queen of the Night''s famous aria?","options":[{"id":"a","text":"Don Giovanni","is_correct":false},{"id":"b","text":"The Marriage of Figaro","is_correct":false},{"id":"c","text":"The Magic Flute","is_correct":true},{"id":"d","text":"Così fan tutte","is_correct":false}],"explanation":"Der Hölle Rache, the Queen of the Night''s aria with its famous high F, appears in The Magic Flute (1791)."},{"id":"q4","question":"Who completed the Requiem that Mozart left unfinished at his death?","options":[{"id":"a","text":"Joseph Haydn","is_correct":false},{"id":"b","text":"Antonio Salieri","is_correct":false},{"id":"c","text":"Franz Xaver Süßmayr","is_correct":true},{"id":"d","text":"Ludwig van Beethoven","is_correct":false}],"explanation":"His pupil Franz Xaver Süßmayr finished the Requiem in 1792, at the request of Mozart''s widow Constanze."},{"id":"q5","question":"At roughly what age did Mozart start composing music?","options":[{"id":"a","text":"Five","is_correct":true},{"id":"b","text":"Nine","is_correct":false},{"id":"c","text":"Thirteen","is_correct":false},{"id":"d","text":"Seventeen","is_correct":false}],"explanation":"He wrote his first small pieces around age five, preserved thanks to his father Leopold."},{"id":"q6","question":"In which city did Mozart live from 1781 until his death?","options":[{"id":"a","text":"Salzburg","is_correct":false},{"id":"b","text":"Vienna","is_correct":true},{"id":"c","text":"Paris","is_correct":false},{"id":"d","text":"London","is_correct":false}],"explanation":"He broke with the Archbishop of Salzburg in 1781 and spent his final decade in Vienna."},{"id":"q7","question":"What was the name of Mozart''s wife?","options":[{"id":"a","text":"Constanze Weber","is_correct":true},{"id":"b","text":"Maria Anna Mozart","is_correct":false},{"id":"c","text":"Aloysia Weber","is_correct":false},{"id":"d","text":"Josepha Weber","is_correct":false}],"explanation":"He married Constanze Weber in 1782; before that he had been in love with her sister, the singer Aloysia."},{"id":"q8","question":"What does the title \"Eine kleine Nachtmusik\" mean?","options":[{"id":"a","text":"\"A little night music\"","is_correct":true},{"id":"b","text":"\"A great symphony\"","is_correct":false},{"id":"c","text":"\"A night at the opera\"","is_correct":false},{"id":"d","text":"\"Music for a small hall\"","is_correct":false}],"explanation":"Serenade No. 13 in G major, K. 525 (1787), translates as ''a little night music'' — a serenade for strings."}]'::jsonb,
  null,
  array['classical music', 'mozart', 'opera', 'composers']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-mozart',
  'Trivia de Mozart: vida, óperas y el Réquiem',
  'Ocho preguntas sobre Wolfgang Amadeus Mozart: su infancia en Salzburgo, las grandes óperas, Eine kleine Nachtmusik y el Réquiem que dejó inconcluso.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'music'),
  '[{"id":"q1","question":"¿En qué ciudad nació Mozart en 1756?","options":[{"id":"a","text":"Viena","is_correct":false},{"id":"b","text":"Salzburgo","is_correct":true},{"id":"c","text":"Praga","is_correct":false},{"id":"d","text":"Múnich","is_correct":false}],"explanation":"Wolfgang Amadeus Mozart nació en Salzburgo el 27 de enero de 1756; ya adulto, en 1781, se mudó a Viena."},{"id":"q2","question":"De niño prodigio, Mozart recorrió Europa actuando junto a qué familiar?","options":[{"id":"a","text":"Su madre, Anna Maria","is_correct":false},{"id":"b","text":"Su hermana Maria Anna, «Nannerl»","is_correct":true},{"id":"c","text":"Su hermano menor","is_correct":false},{"id":"d","text":"Su prima, la «Bäsle»","is_correct":false}],"explanation":"Maria Anna Mozart, apodada Nannerl, también era prodigio del teclado; los hermanos giraron juntos por Europa."},{"id":"q3","question":"¿En qué ópera de Mozart aparece la famosa aria de la Reina de la Noche?","options":[{"id":"a","text":"Don Giovanni","is_correct":false},{"id":"b","text":"Las bodas de Fígaro","is_correct":false},{"id":"c","text":"La flauta mágica","is_correct":true},{"id":"d","text":"Così fan tutte","is_correct":false}],"explanation":"El aria de venganza de la Reina de la Noche, con su célebre fa sobreagudo, está en La flauta mágica (1791)."},{"id":"q4","question":"¿Quién completó el Réquiem que Mozart dejó inconcluso a su muerte?","options":[{"id":"a","text":"Joseph Haydn","is_correct":false},{"id":"b","text":"Antonio Salieri","is_correct":false},{"id":"c","text":"Franz Xaver Süßmayr","is_correct":true},{"id":"d","text":"Ludwig van Beethoven","is_correct":false}],"explanation":"Su alumno Franz Xaver Süßmayr terminó el Réquiem en 1792, por encargo de la viuda de Mozart, Constanze."},{"id":"q5","question":"¿A qué edad aproximada empezó Mozart a componer?","options":[{"id":"a","text":"A los cinco años","is_correct":true},{"id":"b","text":"A los nueve años","is_correct":false},{"id":"c","text":"A los trece años","is_correct":false},{"id":"d","text":"A los diecisiete años","is_correct":false}],"explanation":"Escribió sus primeras piezas hacia los cinco años, conservadas gracias a su padre Leopold."},{"id":"q6","question":"¿En qué ciudad vivió Mozart desde 1781 hasta su muerte?","options":[{"id":"a","text":"Salzburgo","is_correct":false},{"id":"b","text":"Viena","is_correct":true},{"id":"c","text":"París","is_correct":false},{"id":"d","text":"Londres","is_correct":false}],"explanation":"Rompió con el arzobispo de Salzburgo en 1781 y pasó su última década en Viena."},{"id":"q7","question":"¿Cómo se llamaba la esposa de Mozart?","options":[{"id":"a","text":"Constanze Weber","is_correct":true},{"id":"b","text":"Maria Anna Mozart","is_correct":false},{"id":"c","text":"Aloysia Weber","is_correct":false},{"id":"d","text":"Josepha Weber","is_correct":false}],"explanation":"Se casó con Constanze Weber en 1782; antes había estado enamorado de su hermana, la cantante Aloysia."},{"id":"q8","question":"¿Qué significa el título «Eine kleine Nachtmusik»?","options":[{"id":"a","text":"«Una pequeña música nocturna»","is_correct":true},{"id":"b","text":"«Una gran sinfonía»","is_correct":false},{"id":"c","text":"«Una noche en la ópera»","is_correct":false},{"id":"d","text":"«Música para una sala pequeña»","is_correct":false}],"explanation":"La Serenata n.º 13 en sol mayor, K. 525 (1787), se traduce como «una pequeña música nocturna»: una serenata para cuerdas."}]'::jsonb,
  null,
  array['música clásica', 'mozart', 'ópera', 'compositores']::text[],
  3,
  'published',
  false,
  false,
  now()
)
